<template>
  <div class="layout-px-spacing">
    <ul class="navbar-nav flex-row mt-2">
      <li>
        <div class="page-header">
          <nav class="breadcrumb-one" aria-label="breadcrumb">
            <ol class="breadcrumb">
              <li class="breadcrumb-item"><a href="javascript:;">Home</a></li>
              <li class="breadcrumb-item active" aria-current="page">
                <span>Reports & Analytics</span>
              </li>
            </ol>
          </nav>
        </div>
      </li>
    </ul>

    <div class="d-flex justify-content-between align-items-start mb-1">
      <div>
        <h1 class="reports-title mb-0">Reports Library</h1>
        <p class="text-muted mb-0">Standard reports across the modules — pin the ones you use most.</p>
      </div>
      <div class="btn-group">
        <button class="btn btn-dark me-2" @click="getReportCards()"><i class="bi bi-arrow-clockwise"></i></button>
        <button class="btn btn-primary" 
        data-bs-toggle="modal" data-bs-target="#edit"
        ><i class="bi bi-plus-square"/></button>
      </div>
    </div>

    <div class="row mt-3">
      <!-- SIDEBAR -->
      <div class="col-md-3">
        <div class="rl-panel mb-3">
          <div class="rl-panel-label">VIEW</div>
          <ul class="list-unstyled mb-0">
            <li
              class="rl-view-item"
              :class="{ active: activeView === 'standard' }"
              @click="activeView = 'standard'"
            >
              <span><svg class="rl-icon me-2" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/></svg>Standard Reports</span>
              <span class="badge rl-count-badge">{{ reports.length }}</span>
            </li>
            <li
              class="rl-view-item"
              :class="{ active: activeView === 'favourites' }"
              @click="activeView = 'favourites'"
            >
              <span><svg class="rl-icon me-2" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg>Favourites</span>
              <span class="badge rl-count-badge">{{ favouriteCount }}</span>
            </li>
          </ul>
        </div>

        <div class="rl-panel mb-3">
          <div class="rl-panel-label">CATEGORIES</div>
          <span v-if="loading" v-html="rowShimmer(5)"></span>
          <ul v-else class="list-unstyled mb-0">
            <li
              class="rl-cat-item"
              :class="{ active: selectedCategory === 'All' }"
              @click="selectedCategory = 'All'"
            >
              <span class="rl-cat-name text-muted">All</span>
              <span class="badge rl-count-badge">{{ reports.length }}</span>
            </li>
            <li
              v-for="cat in categories"
              :key="cat.name"
              class="rl-cat-item"
              :class="{ active: selectedCategory === cat.name }"
              @click="selectedCategory = cat.name"
            >
              <span class="rl-cat-name">
                <span class="rl-dot" :style="{ backgroundColor: cat.color }"></span>
                {{ cat.name }}
              </span>
              <span class="badge rl-count-badge">{{ categoryCount(cat.name) }}</span>
            </li>
          </ul>
        </div>

        <div class="rl-panel mb-3">
          <div class="rl-panel-label">SORT</div>
          <div class="btn-group w-100" role="group">
            <button
              type="button"
              class="btn btn-sm rl-sort-btn"
              :class="sortBy === 'name' ? 'rl-sort-active' : 'btn-outline-secondary'"
              @click="sortBy = 'name'"
            >
              Name
            </button>
            <button
              type="button"
              class="btn btn-sm rl-sort-btn"
              :class="sortBy === 'category' ? 'rl-sort-active' : 'btn-outline-secondary'"
              @click="sortBy = 'category'"
            >
              Category
            </button>
            <button
              type="button"
              class="btn btn-sm rl-sort-btn"
              :class="sortBy === 'pinned' ? 'rl-sort-active' : 'btn-outline-secondary'"
              @click="sortBy = 'pinned'"
            >
              Pinned
            </button>
          </div>
        </div>

        <button class="btn btn-outline-secondary w-100" @click="resetFilters">
          <svg class="rl-icon me-1" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 12a9 9 0 1 0 3-6.7M3 4v5h5"/></svg> Reset Filters
        </button>
      </div>

      <!-- MAIN -->
      <div class="col-md-9">
        <div class="rl-search-wrap mb-3">
          <svg class="rl-icon rl-search-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="M21 21l-4.35-4.35"/></svg>
          <input
            type="text"
            class="form-control rl-search-input"
            placeholder="Search reports by name, description, category..."
            v-model="searchQuery"
          />
        </div>

        <div v-if="filteredReports.length === 0" class="text-center text-muted py-5">
          No reports match your filters.
        </div>

        <div class="row">
          <span v-if="loading" v-html="cardShimmer()"></span>
          <div
            class="col-md-4 mb-4"
            v-for="report in filteredReports"
            :key="report.id"
          >

            <div class="rl-card" :style="{ borderLeftColor: categoryColor(report.category) }">
              <div class="d-flex justify-content-between align-items-start mb-2">
                <div class="rl-card-title">
                  <span v-if="report.icon" class="rl-card-title-icon text-muted"><i :class="report.icon"></i></span>
                  {{ report.name }}
                </div>
                <svg
                  class="rl-icon rl-star"
                  :class="report.favourite ? 'rl-star-active' : 'rl-star-inactive'"
                  viewBox="0 0 24 24"
                  fill="currentColor"
                  @click.stop="toggleFavourite(report)"
                >
                  <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/>
                </svg>
                <i class="bi bi-pencil-square"
                data-bs-toggle="modal"
                data-bs-target="#edit"
                @click="form = report"
                ></i>
              </div>
                        <router-link :to="report?.path ?? '#'">
              <p class="rl-card-desc">{{ report.description }}</p>
              <span
                class="badge rl-cat-badge"
                :style="{
                  backgroundColor: categoryBg(report.category),
                  color: categoryColor(report.category),
                }"
              >
                <svg class="rl-icon me-1" viewBox="0 0 24 24" fill="currentColor"><path d="M3 6a1 1 0 011-1h5l2 2h9a1 1 0 011 1v10a1 1 0 01-1 1H4a1 1 0 01-1-1V6z"/></svg>{{ report.category.toUpperCase() }}
              </span>
                        </router-link>

            </div>
      

          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- registry for report modal -->
   
                 <div class="modal fade mymodal" id="edit" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel">REPORT REGISTRATION FORM</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close-form" ></button>
      </div>
<div class="modal-body" >
      <div class="row layout-top-spacing" style="max-height: 67vh; overflow-y: auto;">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                      <div class="row">
                        <div class="col-md-3">
                          <label class="form-label">Report Name</label>
                          <input  class="form-control" type="text" placeholder="Enter Report Name" v-model="form.name">
                        </div>

                           <div class="col-md-3">
                          <label class="form-label">Category</label>
                           <select class="form-control" v-model="form.category">
                              <option value="">Select</option>
                              <option v-for="category in categories" :value="category.name">{{ category.name }}</option>
                              <option value="new">New Category</option>
                           </select>
                        </div>

                        <div class="col-md-3" v-if="form.category ==='new'">
                          <label class="form-label">Report Category</label>
                          <input class="form-control" type="text" placeholder="Enter Report Category" v-model="form.new_category">
                        </div>

                        <div class="col-md-3">
                          <label class="form-label">Icon <span class="badge badge-primary"><i  :class="form.icon"></i> </span></label>
                          <input class="form-control" type="text" placeholder="Eg. bi bi-eye-fill" v-model="form.icon">
                        </div>

                        <div class="col-md-3">
                          <label class="form-label">Path</label>
                          <input class="form-control" type="text" placeholder="Eg. /report/path" v-model="form.path">
                        </div>

                        <div class="col-md-12">
                          <label class="form-label">Brief Description</label>
                          <input class="form-control" type="text" placeholder="Enter Description" v-model="form.description">
                        </div>
                      </div>
                    </div>
                </div>
            </div>
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-danger btn-sm py-2 px-2" data-bs-dismiss="modal">Close</button>
        <button type="button" class="btn btn-success btn-sm py-2 px-2" @click="submitForm()" :disabled="saving">
          <span v-if="saving" v-html="loadingSpinner()"/>
          <span v-else>Save</span>
        </button>
      </div>

    </div>
  </div>

</div>

   <!-- registry for report modal -->
</template>

<script setup>
import { ref, computed,inject,onMounted } from "vue";
import { useMeta } from "@/composables/use-meta";
import axios from "axios";
const showMessage = inject("showMessage");
const showError = inject("showError");

useMeta({ title: "Reports Library" });


const cardShimmer = inject('cardShimmer')
const rowShimmer = inject('rowShimmer')
const loadingSpinner = inject('loadingSpinner')
const activeView = ref("standard");
const selectedCategory = ref("All");
const sortBy = ref("pinned");
const searchQuery = ref("");
const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL,
});

const categories = ref([]);

// Static demo data — swap for an API call when ready
const reports = ref([]);

const favouriteCount = computed(() => reports.value.filter((r) => r.favourite).length);

const categoryCount = (name) => reports.value.filter((r) => r.category === name).length;

const categoryColor = (name) => {
  const cat = categories.value.find((c) => c.name === name);
  return cat ? cat.color : "#999999";
};

const categoryBg = (name) => {
  const color = categoryColor(name);
  return color + "1A"; // light tint of the category color
};

const iconPaths = {
  "fa-user": '<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 4-6 8-6s8 2 8 6"/>',
  "fa-list": '<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01" stroke="currentColor" stroke-width="2" fill="none"/>',
  "fa-file-invoice": '<path d="M6 2h9l5 5v15a1 1 0 01-1 1H6a1 1 0 01-1-1V3a1 1 0 011-1z"/><path d="M9 9h6M9 13h6M9 17h4" stroke="#fff" stroke-width="1"/>',
};



const toggleFavourite = (report) => {
  report.favourite = !report.favourite;
};

const resetFilters = () => {
  activeView.value = "standard";
  selectedCategory.value = "All";
  sortBy.value = "pinned";
  searchQuery.value = "";
};

const filteredReports = computed(() => {
  let list = [...reports.value];

  if (activeView.value === "favourites") {
    list = list.filter((r) => r.favourite);
  }

  if (selectedCategory.value !== "All") {
    list = list.filter((r) => r.category === selectedCategory.value);
  }

  if (searchQuery.value.trim()) {
    const q = searchQuery.value.trim().toLowerCase();
    list = list.filter(
      (r) =>
        r.name.toLowerCase().includes(q) ||
        r.description.toLowerCase().includes(q) ||
        r.category.toLowerCase().includes(q)
    );
  }

  if (sortBy.value === "name") {
    list.sort((a, b) => a.name.localeCompare(b.name));
  } else if (sortBy.value === "category") {
    list.sort((a, b) => a.category.localeCompare(b.category));
  } else if (sortBy.value === "pinned") {
    list.sort((a, b) => (b.favourite === true) - (a.favourite === true));
  }

  return list;
});

const loading = ref(false)
const  getReportCards = async ()=>{
  loading.value = true
  try{
  const response = await axiosInstance.get('report-cards')
  reports.value = response.data
  }catch(error){
    showError(error.message)
    console.log(error)
  }finally{
    loading.value= false
  }


} 


const randomColor = () => {
  const r = Math.floor(Math.random() * 100) + 100
  const g = Math.floor(Math.random() * 100) + 100
  const b = Math.floor(Math.random() * 100) + 100

  return `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}`
}


const getCategories = async () => {
  const response = await axiosInstance.get('report-card-categories')

  categories.value = response.data.map(category => ({
    ...category,
    color: randomColor()
  }))
}

const form = ref({
  id : '',
  name : '',
  description: '',
  category : '',
  issuer_id : JSON.parse(localStorage.getItem('user')).id,
  path : '',
  new_category : ''
})

const clearForm = ()=>{
  form.value = {
  id : '',
  name : '',
  description: '',
  category : '',
  path : '',
  new_category : ''
}
}

const saving = ref(false)
const submitForm = async()=>{
    saving.value = true
    const payload = {
      name : form.value.name,
      description : form.value.description,
      issuer_id : JSON.parse(localStorage.getItem('user')).id,
      category : form.value.category ?? form.value.new_category,
      icon :  form.value.icon,
      path : form.value.path
    }
  try{
  if(form.value.id){
    const response = await axiosInstance.put(`update-report-cards/${form.value.id}`,payload)
  }else{
    const response = await axiosInstance.post('store-report-cards',payload)
  }
  showMessage('Data Saved')
  document.getElementById('close-form').click()
  clearForm()
  getReportCards()
  }catch(error){
    showError(error.message)
    console.log(error)
  }finally{
    saving.value= false
  }
}

onMounted(() => {
  getCategories()
   getReportCards()
});


</script>

